set -e
cd "$1"
git init -q .
mkdir -p platform/pipelines
printf '# GENERATED by chorus-make from the graph (#4465). Do not edit: change the rows and regenerate.\nsteps: []\n' > platform/pipelines/zz-tsv-only.yaml
git add -A
